import java.io.*;
import java.util.*;


public class Main {
	static int mod = (int) (1e9+7);
	static InputReader in;
    static PrintWriter out;


		public static void main(String args[] )  {

			in = new InputReader(System.in);
	        out = new PrintWriter(System.out); 
	        Scanner in = new Scanner (System.in);
	       int n = in.nextInt();
	       int B= in.nextInt();
	       int[] a = new int[n];
	       for(int i=0;i<n;i++) {
	    	   		a[i]=in.nextInt();
	       }
	       int ce=0,co=0;
	       //int prev=a[0];
	     //  int[] count = new int[n];
	       ArrayList<Integer> count = new ArrayList<Integer>();
	     //  int v=0;
	     //  Arrays.sort(a);


	       int p=0;
	       for(int i=0;i<n-1;i++) {
	    	   // a[i]=in.nextInt();

	    	   if(a[i]%2==0) {
	    		   ce++;
	    	   }
	    	   else {
	    		   co++;
	    	   }
	    	   //System.out.println(ce+" "+co);
	    	   if(co==ce) {
	    		  // count+=a[i]-prev;
	    		   //System.out.println(a[i]+" "+a[i+1]);
	    		   count.add(Math.abs(a[i]-a[i+1]));
	    		  // p++;
	    	   }
	    	  // prev=a[i];
	       }

	   // System.out.println(p);

	       //Arrays.sort(count);

	       //Arrays.sort(count);
	       Collections.sort(count);

	       int sum=0;
	       int cou=0;
	       for(int i=0;i<count.size();i++) {

	    	   		sum+=count.get(i);

	    	    if(sum>B) {
	 	    		   break;
	 	    	   }
	    		cou++;
	       }
	       System.out.println(cou);
	        in.close();
	        out.close();
		}

		static class InputReader
	    {

	        private final InputStream stream;
	        private final byte[] buf = new byte[8192];
	        private int curChar, snumChars;
	        private SpaceCharFilter filter;

	        public InputReader(InputStream stream)
	        {
	                this.stream = stream;
	        }

	        public int snext()
	        {
	                if (snumChars == -1)
	                        throw new InputMismatchException();
	                if (curChar >= snumChars)
	                {
	                        curChar = 0;
	                        try
	                        {
	                                snumChars = stream.read(buf);
	                        } catch (IOException e)
	                        {
	                                throw new InputMismatchException();
	                        }
	                        if (snumChars <= 0)
	                                return -1;
	                }
	                return buf[curChar++];
	        }

	        public int nextInt()
	        {
	                int c = snext();
	                while (isSpaceChar(c))
	                {
	                        c = snext();
	                }
	                int sgn = 1;
	                if (c == '-')
	                {
	                        sgn = -1;
	                        c = snext();
	                }
	                int res = 0;
	                do
	                {
	                        if (c < '0' || c > '9')
	                                throw new InputMismatchException();
	                        res *= 10;
	                        res += c - '0';
	                        c = snext();
	                } while (!isSpaceChar(c));
	                return res * sgn;
	        }

	        public long nextLong()
	        {
	                int c = snext();
	                while (isSpaceChar(c))
	                {
	                        c = snext();
	                }
	                int sgn = 1;
	                if (c == '-')
	                {
	                        sgn = -1;
	                        c = snext();
	                }
	                long res = 0;
	                do
	                {
	                        if (c < '0' || c > '9')
	                                throw new InputMismatchException();
	                        res *= 10;
	                        res += c - '0';
	                        c = snext();
	                } while (!isSpaceChar(c));
	                return res * sgn;
	        }

	        public int[] nextIntArray(int n)
	        {
	                int a[] = new int[n];
	                for (int i = 0; i < n; i++)
	                {
	                        a[i] = nextInt();
	                }
	                return a;
	        }

	        public long[] nextLongArray(int n)
	        {
	                long a[] = new long[n];
	                for (int i = 0; i < n; i++)
	                {
	                        a[i] = nextLong();
	                }
	                return a;
	        }

	        public String readString()
	        {
	                int c = snext();
	                while (isSpaceChar(c))
	                {
	                        c = snext();
	                }
	                StringBuilder res = new StringBuilder();
	                do
	                {
	                        res.appendCodePoint(c);
	                        c = snext();
	                } while (!isSpaceChar(c));
	                return res.toString();
	        }

	        public String nextLine()
	        {
	                int c = snext();
	                while (isSpaceChar(c))
	                        c = snext();
	                StringBuilder res = new StringBuilder();
	                do
	                {
	                        res.appendCodePoint(c);
	                        c = snext();
	                } while (!isEndOfLine(c));
	                return res.toString();
	        }

	        public boolean isSpaceChar(int c)
	        {
	                if (filter != null)
	                        return filter.isSpaceChar(c);
	                return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
	        }

	        private boolean isEndOfLine(int c)
	        {
	                return c == '\n' || c == '\r' || c == -1;
	        }

	        public interface SpaceCharFilter
	        {
	                public boolean isSpaceChar(int ch);
	        }

	    }
}

